import type { MetadataRoute } from 'next'

// Web app manifest. Generated by Next.js at /manifest.webmanifest and linked
// automatically in <head>. Kept as display: 'browser' so the site keeps its
// normal browser chrome - this is a discoverability/SEO signal, not a PWA.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'Thibault GAREL - AI Engineer Portfolio',
    short_name: 'T. GAREL',
    description:
      'Portfolio of Thibault GAREL, AI engineering student at École Polytechnique (Master 2 Data Science, double degree with ECE Paris).',
    start_url: '/',
    display: 'browser',
    background_color: '#ffffff',
    theme_color: '#ffffff',
    icons: [
      { src: '/favicon.ico', sizes: '16x16 32x32 48x48', type: 'image/x-icon' },
      { src: '/icon.png', sizes: '460x460', type: 'image/png' },
    ],
  }
}
